+static int serial_ambarella_poll_get_char(struct uart_port *port)
+{
+	if (port->suspended)
+		return NO_POLL_CHAR;
+
+	if (wait_for_rx(port))
+		return NO_POLL_CHAR;
+
+	return readl_relaxed(port->membase + UART_RB_OFFSET);
+}
